import { lookupOrder } from './order.service';

export function refundOrder(orderId: string): void {
  const order = lookupOrder(orderId);

  if (!order) {
    throw new Error(`Order ${orderId} not found`);
  }

  if (order.refunded) {
    throw new Error(`Order ${orderId} has already been refunded`);
  }

  if (order.total < 10) {
    throw new Error(`Order ${orderId} total is less than 10 and cannot be refunded`);
  }

  (order as any).refunded = true;
}

